    }
    if let item = minSpeed {
      raw.fields |= MLN_MOMENTUM_DECAY_MIN_SPEED.rawValue; raw.min_speed = item
    }
    if let item = maxSpeed {
      raw.fields |= MLN_MOMENTUM_DECAY_MAX_SPEED.rawValue; raw.max_speed = item
    }
